package com.kennedy.wallet.config;
import com.kennedy.wallet.service.JwtService;import com.kennedy.wallet.repository.UserRepository;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.cors.CorsConfiguration;
@Configuration @EnableMethodSecurity @org.springframework.boot.context.properties.EnableConfigurationProperties({WalletProperties.class,MpesaProperties.class,NotificationProperties.class}) public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
 @Bean SecurityFilterChain filterChain(HttpSecurity http,JwtService jwt,UserRepository users,WalletProperties p)throws Exception{http.csrf(c->c.disable()).cors(c->c.configurationSource(req->{CorsConfiguration cc=new CorsConfiguration();cc.setAllowedOrigins(p.getCors().getAllowedOrigins());cc.setAllowedMethods(java.util.List.of("GET","POST","OPTIONS"));cc.setAllowedHeaders(java.util.List.of("Authorization","Content-Type","X-Request-Id","Idempotency-Key"));return cc;})).headers(h->h.contentTypeOptions(c->{}).frameOptions(f->f.deny()).httpStrictTransportSecurity(x->x.includeSubDomains(true))).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a
         .requestMatchers("/api/auth/**","/api/mpesa/callback/**","/actuator/health/**","/actuator/info","/v3/api-docs/**","/swagger-ui/**").permitAll()
         .requestMatchers("/actuator/**").hasRole("ADMIN")
         .anyRequest().authenticated()).addFilterBefore(new JwtAuthFilter(jwt,users),UsernamePasswordAuthenticationFilter.class);return http.build();}
 @Bean org.springframework.security.core.userdetails.UserDetailsService walletUserDetailsService(UserRepository users){return phone->users.findByPhone(phone)
         .map(user->org.springframework.security.core.userdetails.User.withUsername(user.getPhone()).password(user.getPasswordHash()).roles(user.getRole().name()).disabled(!user.isEnabled()).build())
         .orElseThrow(()->new org.springframework.security.core.userdetails.UsernameNotFoundException("User not found"));}
 @Bean org.springframework.boot.ApplicationRunner prodJwtGuard(WalletProperties p,MpesaProperties mpesa,NotificationProperties notifications,org.springframework.core.env.Environment env){return args->{if(java.util.Arrays.asList(env.getActiveProfiles()).contains("prod")){String s=p.getJwt().getSecret();if(s==null||s.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<32||s.startsWith("dev-only"))throw new IllegalStateException("JWT_SECRET must be configured with at least 32 bytes in prod");if(java.util.stream.Stream.of(mpesa.getConsumerKey(),mpesa.getConsumerSecret(),mpesa.getShortcode(),mpesa.getPasskey(),mpesa.getCallbackToken(),mpesa.getCallbackBaseUrl()).anyMatch(v->v==null||v.isBlank())||mpesa.getCallbackToken().length()<32||!mpesa.getCallbackToken().matches("[A-Za-z0-9_-]+")||!mpesa.getCallbackBaseUrl().startsWith("https://"))throw new IllegalStateException("M-Pesa credentials and secure callback configuration are required in prod");if(notifications.getApiKey().isBlank()||notifications.getUsername().isBlank())throw new IllegalStateException("Africa's Talking credentials are required in prod");}};}
}
